import {knowledge,topicFor,emergencyText} from './chat-knowledge.js';
let language=document.documentElement.lang, history=[],active=null,generation=0,busy=false;
const host=document.createElement('div');host.id='chat-widget';document.body.append(host);
const words={en:{launcher:'Need help?',title:'HighGround guide',subtitle:'Resource assistant · Not an emergency service',close:'Close chat',greeting:'Hi! I can help you explore HighGround and flood-related resources. Choose a topic or ask a short question. This is a demo: I cannot send help, verify availability, or assess a medical situation. Please use fictional details only.',question:'Your question',placeholder:'Ask about care or resources…',send:'Send question',clear:'Clear chat',privacy:'When AI is connected, your message and recent chat are sent to OpenAI for replies. Avoid personal or medical information. Clearing chat removes it from this page only; OpenAI may retain data under its policies. No requests are sent to responders.',waiting:'Preparing a reply…',fallback:'AI unavailable · From our resource guide:',ai:'AI reply · May contain mistakes',guidance:'Emergency guidance',emergency:'Immediate danger? Call 911',resources:'Real resources: 2-1-1 Texas',topics:'Suggested topics',log:'Conversation',mode:'Checking AI connection…',ready:'AI enabled · Can make mistakes',offline:'Resource guide only · AI not connected',limited:'Too many questions. Please wait a minute. ',error:'Use a question of 1–500 characters.',reset:'Chat cleared.'},es:{launcher:'¿Necesitas ayuda?',title:'Guía de HighGround',subtitle:'Asistente de recursos · No es un servicio de emergencia',close:'Cerrar chat',greeting:'¡Hola! Puedo orientarte sobre HighGround y recursos ante inundaciones. Elige un tema o escribe una pregunta breve. Esta es una demo: no envío ayuda, verifico disponibilidad ni evalúo situaciones médicas. Usa solo información ficticia.',question:'Tu pregunta',placeholder:'Pregunta sobre atención o recursos…',send:'Enviar pregunta',clear:'Borrar chat',privacy:'Cuando la IA está conectada, tu mensaje y el contexto reciente se envían a OpenAI para responder. Evita información personal o médica. Borrar el chat solo lo elimina de esta página; OpenAI puede conservar datos según sus políticas. No se envían solicitudes a servicios de emergencia.',waiting:'Preparando respuesta…',fallback:'IA no disponible · De nuestra guía de recursos:',ai:'Respuesta de IA · Puede contener errores',guidance:'Orientación de emergencia',emergency:'¿Peligro inmediato? Llama al 911',resources:'Recursos reales: 2-1-1 Texas',topics:'Temas sugeridos',log:'Conversación',mode:'Comprobando conexión de IA…',ready:'IA habilitada · Puede cometer errores',offline:'Solo guía de recursos · IA no conectada',limited:'Demasiadas preguntas. Espera un minuto. ',error:'Escribe una pregunta de 1 a 500 caracteres.',reset:'Chat borrado.'}};
let configured=false;const w=()=>words[language];
function cancel(){generation++;active?.abort();active=null;busy=false;history=[];}
function mount(){const c=w();host.innerHTML=`<button id="chat-launcher" class="chat-launcher" aria-haspopup="dialog" aria-controls="flood-chat" aria-expanded="false"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M21 11a9 9 0 0 1-9 9H5l-3 2V11a9 9 0 0 1 19 0Z M7 9h9 M7 13h6"/></svg><span>${c.launcher}</span></button><dialog id="flood-chat" class="chat-panel" aria-labelledby="chat-title" aria-describedby="chat-description"><div class="chat-header"><div><h2 id="chat-title">${c.title}</h2><p id="chat-description">${c.subtitle}</p></div><button id="chat-close" aria-label="${c.close}">×</button></div><a class="chat-emergency" href="tel:911">${c.emergency} ↗</a><p id="chat-mode" class="chat-mode">${configured?c.ready:c.offline}</p><div id="chat-log" class="chat-log" role="log" aria-live="polite" aria-relevant="additions" aria-label="${c.log}"></div><p id="chat-status" role="status" class="chat-status"></p><div class="chat-topics" aria-label="${c.topics}">${knowledge[language].map(x=>`<button type="button" data-topic="${x.id}">${x.label}</button>`).join('')}</div><form id="chat-form" class="chat-form"><label for="chat-input">${c.question}</label><div><input id="chat-input" maxlength="500" required autocomplete="off" placeholder="${c.placeholder}"><button type="submit" aria-label="${c.send}">↑</button></div></form><div class="chat-footer"><a href="https://www.211texas.org/">${c.resources} ↗</a><button id="chat-reset">${c.clear}</button></div><p class="chat-privacy">${c.privacy}</p></dialog>`;
 const panel=host.querySelector('dialog'),launcher=host.querySelector('#chat-launcher');
 launcher.onclick=()=>{if(panel.open){panel.close();return}panel.show();launcher.setAttribute('aria-expanded','true');host.querySelector('#chat-close').focus()};host.querySelector('#chat-close').onclick=()=>panel.close();panel.addEventListener('close',()=>{launcher.setAttribute('aria-expanded','false');launcher.focus()});
 host.querySelectorAll('[data-topic]').forEach(b=>b.onclick=()=>reply(knowledge[language].find(x=>x.id===b.dataset.topic).question));
 host.querySelector('#chat-form').onsubmit=e=>{e.preventDefault();const input=host.querySelector('#chat-input');const message=input.value.trim();if(!message||message.length>500){host.querySelector('#chat-status').textContent=c.error;return}if(busy)return;input.value='';reply(message);input.focus()};
 host.querySelector('#chat-reset').onclick=()=>{cancel();setBusy(false);host.querySelector('#chat-log').replaceChildren();append(c.greeting,'bot');host.querySelector('#chat-input').value='';host.querySelector('#chat-status').textContent=c.reset;host.querySelector('#chat-input').focus()};append(c.greeting,'bot');}
function append(text,kind,label){const log=host.querySelector('#chat-log'),bubble=document.createElement('div');bubble.className='chat-message chat-'+kind;if(label){const small=document.createElement('small');small.textContent=label;bubble.append(small)}const p=document.createElement('p');p.textContent=text;bubble.append(p);log.append(bubble);while(log.children.length>25)log.children[1].remove();log.scrollTop=log.scrollHeight;}
function setBusy(value){busy=value;host.querySelector('#chat-form button').disabled=value;host.querySelectorAll('[data-topic]').forEach(b=>b.disabled=value);host.querySelector('#chat-status').textContent=value?w().waiting:'';}
async function reply(message){if(busy)return;const c=w();append(message,'user');if(emergencyText(message)){append(language==='es'?'Si estás en peligro inmediato o tienes una emergencia médica, llama al 911 ahora. No esperes aquí. Este chat no puede enviar ayuda ni evaluar tu situación. No camines ni conduzcas por agua de inundación.':'If you are in immediate danger or have a medical emergency, call 911 now. Do not wait here. This chat cannot send help or assess your situation. Do not walk or drive through floodwater.','bot',c.guidance);return}setBusy(true);const current=++generation;const controller=new AbortController();active=controller;const timeout=setTimeout(()=>controller.abort(),25000);try{const response=await fetch('/api/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({lang:language,messages:[...history.slice(-8),{role:'user',content:message}]}),signal:controller.signal});if(!response.ok)throw Error(response.status===429?'limited':'unavailable');const data=await response.json();if(typeof data.answer!=='string'||!data.answer.trim())throw Error();if(current!==generation)return;append(data.answer,'bot',data.mode==='guidance'?c.guidance:c.ai);history=[...history,{role:'user',content:message},{role:'assistant',content:data.answer}].slice(-8)}catch(error){if(current!==generation)return;append((error.message==='limited'?c.limited:'')+knowledge[language].find(x=>x.id===topicFor(message)).answer,'bot',c.fallback)}finally{clearTimeout(timeout);if(current===generation){active=null;setBusy(false)}}}
document.addEventListener('keydown',e=>{const panel=host.querySelector('dialog');if(e.key==='Escape'&&panel?.open){e.preventDefault();panel.close()}});
window.addEventListener('floodcare-language',e=>{cancel();language=e.detail;mount()});window.addEventListener('pagehide',cancel);mount();
fetch('/api/chat/status').then(r=>r.ok?r.json():null).then(data=>{configured=data?.configured===true;host.querySelector('#chat-mode').textContent=configured?w().ready:w().offline}).catch(()=>{});
